CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, available_balance NUMERIC(15,2) NOT NULL DEFAULT 1000000, used_margin NUMERIC(15,2) NOT NULL DEFAULT 0, total_pnl NUMERIC(15,2) NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watchlist (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, symbol TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, symbol));
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, symbol TEXT NOT NULL, side TEXT NOT NULL CHECK(side IN ('BUY','SELL')), quantity INTEGER NOT NULL CHECK(quantity > 0), price NUMERIC(15,2), order_type TEXT NOT NULL CHECK(order_type IN ('MARKET','LIMIT')), status TEXT NOT NULL CHECK(status IN ('PENDING','EXECUTED','CANCELLED','REJECTED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), executed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS positions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, symbol TEXT NOT NULL, quantity INTEGER NOT NULL, avg_price NUMERIC(15,2) NOT NULL, realized_pnl NUMERIC(15,2) NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, symbol));
CREATE TABLE IF NOT EXISTS trades (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID NOT NULL REFERENCES orders(id), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, symbol TEXT NOT NULL, side TEXT NOT NULL, quantity INTEGER NOT NULL, price NUMERIC(15,2) NOT NULL, pnl NUMERIC(15,2) NOT NULL DEFAULT 0, executed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_user_status_idx ON orders(user_id, status);
CREATE INDEX IF NOT EXISTS trades_user_time_idx ON trades(user_id, executed_at DESC);
